// ❌ BAD: Hardcoding objects everywhere
dispatch({ type: 'ADD_TODO', payload: 'Buy milk' });
dispatch({ type: 'ADD_TODO', payload: 'Do laundry' });

// ✅ GOOD: Using an Action Creator
function addTodo(taskText) {
  return {
    type: 'ADD_TODO',
    payload: taskText
  };
}

dispatch(addTodo('Buy milk'));
dispatch(addTodo('Do laundry'));
